class WordDictionary {
    static class Node{
        Node[] next=new Node[26];
        boolean word;
    }
    private final Node root=new Node();
    public void addWord(String word){
        Node node=root;
        for(char c:word.toCharArray()){
            int i=c-'a';
            if(node.next[i]==null)node.next[i]=new Node();
            node=node.next[i];
        }
        node.word=true;
    }
    public boolean search(String word){
        return dfs(root,word,0);
    }
    private boolean dfs(Node node,String word,int index){
        if(index==word.length())return node.word;
        char c=word.charAt(index);
        if(c!='.')return node.next[c-'a']!=null&&dfs(node.next[c-'a'],word,index+1);
        for(Node child:node.next)if(child!=null&&dfs(child,word,index+1))return true;
        return false;
    }
}

